func ActorLabel(actor *history.Actor) string {
	switch {
	case actor == nil:
		return "Not recorded"
	case actor.ID == ops.RecoveryActor:
		return "Ludock (automatic restart)"
	case actor.Name != "":
		return actor.Name
	case actor.ID != "":
		return "User " + actor.ID + " (name unavailable)"
	}
	return "Not recorded"
}

